const items = $input.all();

return items.map(item => {
  const lead = item.json;

  const subject =
    lead.personalizedSubject ||
    `Quick idea for ${lead.company}`;

  const body =
    lead.personalizedEmail ||
    `Hi ${lead.firstName},\n\nI wanted to reach out regarding ${lead.company}.`;

  return {
    json: {
      ...lead,
      subject,
      body,
      sendgridPayload: {
        personalizations: [
          {
            to: [
              {
                email: lead.email,
                name: lead.fullName
              }
            ],
            subject
          }
        ],
        from: {
          email: lead.fromEmail,
          name: lead.fromName
        },
        content: [
          {
            type: "text/plain",
            value: body
          }
        ]
      }
    }
  };
});

