const items = $input.all();

return items.map(item => {
  const lead = item.json;

  const firstName = lead.firstName || 'there';
  const company = lead.company || 'your company';
  const title = lead.title || 'business leader';
  const offer = lead.offer || 'AI-powered workflow automation';
  const calendarLink = lead.calendarLink || '';

  const subject = `${firstName}, quick idea for ${company}`;

  const body = `Hi ${firstName},

I came across ${company} and noticed you're the ${title}.

I help businesses eliminate repetitive sales and outreach work using ${offer}. The goal is simple: generate more qualified opportunities while reducing the amount of manual prospecting and follow-up required.

I thought there could be an interesting automation opportunity for ${company}.

Would you be open to a quick conversation?

${calendarLink}

Best,
Demo Sender
ABM Solutions`;

  return {
    json: {
      ...lead,
      personalizedSubject: subject,
      personalizedEmail: body,
      personalizationMethod: 'Demo AI Simulation'
    }
  };
});

const items = $input.all();

return items.map(item => {
  const lead = item.json;

  return {
    json: {
      ...lead,
      emailStatus: "SIMULATED_SEND_SUCCESS",
      demoMode: true,
      sentTo: lead.email,
      sentSubject: lead.subject,
      sentBody: lead.body,
      simulatedAt: new Date().toISOString()
    }
  };
});

const items = $input.all();

return items.map((item, index) => {
  const lead = item.json;

  return {
    json: {
      ...lead,
      hubspotStatus: "SIMULATED_CONTACT_CREATED",
      hubspotDemoMode: true,
      simulatedContactId: `demo-contact-${index + 1}`,
      crmRecord: {
        email: lead.email,
        firstName: lead.firstName,
        lastName: lead.lastName,
        company: lead.company,
        title: lead.title,
        website: lead.website,
        lifecycleStage: "lead"
      },
      hubspotSimulatedAt: new Date().toISOString()
    }
  };
});

const items = $input.all();

return items.map(item => {
  const lead = item.json;

  const slackMessage =
    `New outreach activity\n` +
    `Lead: ${lead.fullName}\n` +
    `Title: ${lead.title}\n` +
    `Company: ${lead.company}\n` +
    `Email: ${lead.email}\n` +
    `Subject: ${lead.subject}\n` +
    `CRM Status: ${lead.hubspotStatus || "SIMULATED_CONTACT_CREATED"}\n` +
    `Email Status: ${lead.emailStatus || "SIMULATED_SEND_SUCCESS"}`;

  return {
    json: {
      ...lead,
      slackStatus: "SIMULATED_NOTIFICATION_SENT",
      slackDemoMode: true,
      slackMessage,
      slackSimulatedAt: new Date().toISOString()
    }
  };
});
